-- Índices para tabla cases (5 índices)
CREATE INDEX IF NOT EXISTS idx_cases_status ON cases(status);
CREATE INDEX IF NOT EXISTS idx_cases_priority ON cases(priority);
CREATE INDEX IF NOT EXISTS idx_cases_case_type ON cases(caseType);
CREATE INDEX IF NOT EXISTS idx_cases_created_at ON cases(createdAt);
CREATE INDEX IF NOT EXISTS idx_cases_status_created_at ON cases(status, createdAt);

-- Índices para tabla recognitions (4 índices)
CREATE INDEX IF NOT EXISTS idx_recognitions_to_user_id ON recognitions(to_user_id);
CREATE INDEX IF NOT EXISTS idx_recognitions_read_at ON recognitions(read_at);
CREATE INDEX IF NOT EXISTS idx_recognitions_created_at ON recognitions(created_at);
CREATE INDEX IF NOT EXISTS idx_recognitions_to_user_read ON recognitions(to_user_id, read_at);

-- Índices para tabla survey_responses (3 índices)
CREATE INDEX IF NOT EXISTS idx_survey_responses_survey_id ON survey_responses(survey_id);
CREATE INDEX IF NOT EXISTS idx_survey_responses_user_id ON survey_responses(user_id);
CREATE INDEX IF NOT EXISTS idx_survey_responses_survey_user ON survey_responses(survey_id, user_id);

-- Índices para tabla employees (2 índices)
CREATE INDEX IF NOT EXISTS idx_employees_department_id ON employees(departmentId);
CREATE INDEX IF NOT EXISTS idx_employees_position_id ON employees(positionId);

-- Verificar índices creados
SELECT 'cases' as tabla, COUNT(*) as indices FROM information_schema.statistics WHERE table_name = 'cases' AND table_schema = DATABASE()
UNION ALL
SELECT 'recognitions', COUNT(*) FROM information_schema.statistics WHERE table_name = 'recognitions' AND table_schema = DATABASE()
UNION ALL
SELECT 'survey_responses', COUNT(*) FROM information_schema.statistics WHERE table_name = 'survey_responses' AND table_schema = DATABASE()
UNION ALL
SELECT 'employees', COUNT(*) FROM information_schema.statistics WHERE table_name = 'employees' AND table_schema = DATABASE();

